#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> numbers = {64, 25, 12, 22, 11, 90, 45};
    sort(numbers.begin(), numbers.end());

    cout << "==========================================" << endl;
    cout << "C++ 20 Vector Sorting Engine" << endl;
    cout << "==========================================" << endl;
    cout << "Sorted Numbers: ";
    for (int n : numbers) {
        cout << n << " ";
    }
    cout << endl << "C++ Program Executed Successfully." << endl;
    return 0;
}
